"""Language-complete labels added by the dashboard localization audit.

The main dashboard module contains the older label groups.  This overlay fills
every gap in those groups without allowing a supported profile language to
inherit English.  Rows are stored by message so translators can compare every
shipped language side by side and placeholder parity remains obvious.
"""

from __future__ import annotations

SUPPORTED_DASHBOARD_LANGUAGES = (
    "en", "el", "de", "fr", "es", "it", "pt", "nl",
    "pl", "ru", "uk", "tr", "zh", "ja", "ko",
)

_EXTENDED_LANGUAGES = (
    "fr", "es", "it", "pt", "nl", "pl",
    "ru", "uk", "tr", "zh", "ja", "ko",
)

DASHBOARD_LANGUAGE_AUDIT_TEXT: dict[str, dict[str, str]] = {
    code: {} for code in SUPPORTED_DASHBOARD_LANGUAGES
}


def _add_rows(
    rows: dict[str, tuple[str, ...]], languages: tuple[str, ...]
) -> None:
    """Add aligned translation rows and fail fast on malformed catalogs."""
    for key, values in rows.items():
        if len(values) != len(languages):
            raise RuntimeError(
                f"Dashboard translation row {key!r} has {len(values)} values; "
                f"expected {len(languages)}"
            )
        for language, value in zip(languages, values, strict=True):
            if not str(value).strip():
                raise RuntimeError(
                    f"Dashboard translation {language}.{key} is empty"
                )
            DASHBOARD_LANGUAGE_AUDIT_TEXT[language][key] = value


